function binarySearchableNumbers(nums) {
  const n = nums.length;
  const suffixMin = new Array(n + 1).fill(Infinity);
  for (let i = n - 1; i >= 0; i--) {
    suffixMin[i] = Math.min(suffixMin[i + 1], nums[i]);
  }

  let prefixMax = -Infinity;
  let count = 0;
  for (let i = 0; i < n; i++) {
    if (nums[i] > prefixMax && nums[i] < suffixMin[i + 1]) {
      count++;
    }
    prefixMax = Math.max(prefixMax, nums[i]);
  }
  return count;
}

