function binarySearchableNumbers(nums) {
  // Explore every possible pivot choice for every target directly.
  let total = 0;
  for (let p = 0; p < nums.length; p++) {
    const target = nums[p];
    const memo = new Map();
    const sure = (lo, hi) => {
      const key = lo * 1000 + hi;
      if (memo.has(key)) return memo.get(key);
      let ok = true;
      for (let k = lo; k <= hi && ok; k++) {
        if (k === p) continue;
        if (nums[k] < target) ok = k < p && sure(k + 1, hi);
        else ok = k > p && sure(lo, k - 1);
      }
      memo.set(key, ok);
      return ok;
    };
    if (sure(0, nums.length - 1)) total++;
  }
  return total;
}

