function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const span = size === 'large' ? 100000 : 12;
  const seen = new Set();
  while (seen.size < n) seen.add(Math.floor(rand() * (2 * span + 1)) - span);
  const nums = [...seen];
  const mode = rand();
  if (mode < 0.6) {
    // Mostly sorted with a few swaps, so many values stay searchable.
    nums.sort((a, b) => a - b);
    const swaps = size === 'large' ? Math.floor(rand() * 40) : Math.floor(rand() * 3);
    for (let s = 0; s < swaps; s++) {
      const i = Math.floor(rand() * n);
      const j = Math.min(n - 1, i + 1 + Math.floor(rand() * (size === 'large' ? 30 : 3)));
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  } else if (mode < 0.75) {
    nums.sort((a, b) => b - a);
  }
  return [nums];
}
